const localeOptions = ['en', 'fr', 'de', 'es-ES', 'es-419', 'zh-CN'];
const languageNames = {
  en: 'Language',
  fr: 'Langue',
  de: 'Sprache',
  'es-ES': 'Idioma',
  'es-419': 'Idioma',
  'zh-CN': '语言',
};

function applyLocale(locale) {
  const selected = localeOptions.includes(locale) ? locale : 'es-419';
  const translations = policyTranslations[selected] ?? {};
  document.documentElement.lang = selected;
  document.title = `${translations.title ?? 'Tratamiento de datos personales y cookies'} | Gestourant`;
  const description = document.querySelector('meta[name="description"]');
  if (description) description.content = translations.title ?? 'Aviso informativo sobre tratamiento de datos personales y cookies de Gestourant.';
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const translation = translations[element.dataset.i18n];
    if (translation) element.textContent = translation;
  });
  const selector = document.querySelector('#policy-language');
  if (selector) {
    selector.value = selected;
    selector.setAttribute('aria-label', languageNames[selected]);
  }
}

const selector = document.querySelector('#policy-language');
const storedLocale = localStorage.getItem('gestourant_locale');
applyLocale(storedLocale);
selector?.addEventListener('change', () => {
  localStorage.setItem('gestourant_locale', selector.value);
  applyLocale(selector.value);
  window.dispatchEvent(new CustomEvent('gestourant:locale-change', { detail: selector.value }));
});
window.addEventListener('gestourant:locale-change', event => applyLocale(event.detail));
window.addEventListener('storage', event => {
  if (event.key === 'gestourant_locale') applyLocale(event.newValue);
});
